import fastparse._, NoWhitespace._

def number[$: P] = P( CharIn("0-9").rep(1).!.map(_.toInt) )
def factor[$: P] = P( number | "(" ~/ expr ~ ")" )
def term[$: P]   = P( factor ~ (CharIn("*/").! ~/ factor).rep ).map(eval)
def expr[$: P]   = P( term   ~ (CharIn("+\\-").! ~/ term).rep ).map(eval)

val Parsed.Success(v, _) = parse("1+2*3", expr(_))
